sys_script.script:
/*
    Before Business Rule - Applies Change Template (child templates applied with after business rule)
*/
(function executeRule(current, previous /*null when async*/) {
    var template_id = current.getValue("template_id");
	var number = current.getValue("u_number");
	var correlation_id = current.getValue("u_correlation_id");
	var logId = correlation_id;
	if (number) {
		logId = number;
	}
	gs.info("["+logId+"][Before rule] Executing Apply template before BR "+ template_id);
	applyTemplate(current);

    function applyTemplate(current){
		try {
			var gr = new GlideRecord('sys_template');
			if(gr.get(template_id)){
				gs.info("["+logId+"][Before rule]Applying template :"+template_id);
				var templateArray = gr.getValue('template').toString().split('^') || '';
				for(var i=0; i<templateArray.length; i++){
					var templatefield = templateArray[i].toString().split('=');
					gs.info("["+logId+"][Before rule]Template field :"+templatefield);
					if(templatefield != 'EQ'){
						current.setValue(["u_" + templatefield[0]], templatefield[1]);
					}
				}
				var templateDetails = new GlideRecord('std_change_record_producer');
				if (templateDetails.get('template', template_id)) {
					var currentVersion = templateDetails.getElement('current_version');
					if(currentVersion){
						gs.info("["+logId+"][Before rule]Current Version is :"+ currentVersion);
						current.setValue("u_std_change_producer_version", currentVersion);
					} else {
						gs.info("["+logId+"][Before rule]Current version is empty");
					}
				} else {
					gs.info("["+logId+"][Before rule]Version information is not there :"+ template_id);
				}
			} else {
				gs.info("["+logId+"][Before rule] Can't find a Template in Producer Table:"+ template_id);
			}
		} catch (e) {
			gs.info("["+logId+"][Before rule] Exception happened during before BR ["+ e +"]");
		}
    }
})(current, previous);
